def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = 9
    row_bands = []
    start = 0
    for r in range(h):
        if all(v == sep for v in grid[r]):
            row_bands.append((start, r))
            start = r + 1
    row_bands.append((start, h))

    col_bands = []
